(1078238, 130762, 8842, '<td valign="top">Not a bad photo but does not meet the challenge requirements.</td>', 'Not a bad photo but does not meet the challenge requirements.', '2004-12-27 00:11:05.000000', NULL, 1),
(1078240, 130846, 8842, '<td valign="top">Awesome composition, I love the painted look you achieved with this lighting.</td>', 'Awesome composition, I love the painted look you achieved with this lighting.', '2004-12-27 00:11:43.000000', NULL, 1),
