(1081533, 130805, 10047, '<td valign="top">Lightinh is a bit harsh, and the missing side panel is a distraction. Ilike the texture and color of the background.</td>', 'Lightinh is a bit harsh, and the missing side panel is a distraction. Ilike the texture and color of the background.', '2004-12-29 12:53:40.000000', NULL, 1),
(1081534, 130824, 8759, '<td valign="top">Too noisy for my taste. Lightning would be better if achieved a more uniform one.</td>', 'Too noisy for my taste. Lightning would be better if achieved a more uniform one.', '2004-12-29 12:53:43.000000', NULL, 1),
