(1084350, 130703, 8637, '<td valign="top">Beautiful, original work.  Excellent composition.  Little focus problem on mouth and left ear...but really nice idea...this has to ribbon!</td>', 'Beautiful, original work.  Excellent composition.  Little focus problem on mouth and left ear...but really nice idea...this has to ribbon!', '2004-12-31 12:25:38.000000', NULL, 1),
(1084351, 130642, 8637, '<td valign="top">Great catch and composition...would be better for me if the illumination on the "face" was a little better for contrast with backgroun...but very nice concept...and I am sure this will ribbon.</td>', 'Great catch and composition...would be better for me if the illumination on the "face" was a little better for contrast with backgroun...but very nice concept...and I am sure this will ribbon.', '2004-12-31 12:26:58.000000', NULL, 1),
