(1087858, 130305, 9906, '<td valign="top">Very very cute!<br/>TC</td>', 'Very very cute!TC', '2005-01-02 23:37:20.000000', NULL, 1),
(1087891, 130703, 29477, '<td valign="top">Congrats...This was one of my highest rated images...Wonderful job!!!<br/></td>', 'Congrats...This was one of my highest rated images...Wonderful job!!!', '2005-01-03 00:01:19.000000', NULL, 0),
(1087896, 130703, 1827, '<td valign="top">WOW!  I didn''t vote or view these images because time was so short, but this is amazing!  Great find, and nicely captured!</td>', 'WOW!  I didn''t vote or view these images because time was so short, but this is amazing!  Great find, and nicely captured!', '2005-01-03 00:02:45.000000', NULL, 0),
(1087897, 130823, 18552, '<td valign="top">Congratulations on your Top 10 finish! This is a super picture.</td>', 'Congratulations on your Top 10 finish! This is a super picture.', '2005-01-03 00:02:59.000000', NULL, 0),
(1087901, 130807, 23394, '<td valign="top">alright shannon!  great job with the lighting.  guess it would look better with a bit more blue and a little less red, but hey, a ribbon''s a ribbon!  way to go!</td>', 'alright shannon!  great job with the lighting.  guess it would look better with a bit more blue and a little less red, but hey, a ribbon''s a ribbon!  way to go!', '2005-01-03 00:03:47.000000', NULL, 0),
(1087919, 130703, 16479, '<td valign="top">hahaha....congrats on this one....</td>', 'hahaha....congrats on this one....', '2005-01-03 00:08:47.000000', NULL, 0),
