INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1087943, 130566, 23394, '<td valign="top">ok, max, i know this is a tough lesson, but i also know you can take it.  one of the key things to learn here is the difference between a ''portfolio'' shot and a ''challenge'' shot.  save this stuff for your portfolio...it is Great!  but don''t do this for challenges...you see what happens.<br/> <br/>check out shannon calvert''s thread about the recipe for ribbonning.  you have definitely got an eye and a sense of humor.  if you get it under control, you could easily add 2 pts to your scores.  it''s not automatic, but you can do it if you apply yourself!  go for it!</td>', 'ok, max, i know this is a tough lesson, but i also know you can take it.  one of the key things to learn here is the difference between a ''portfolio'' shot and a ''challenge'' shot.  save this stuff for your portfolio...it is Great!  but don''t do this for challenges...you see what happens. check out shannon calvert''s thread about the recipe for ribbonning.  you have definitely got an eye and a sense of humor.  if you get it under control, you could easily add 2 pts to your scores.  it''s not automatic, but you can do it if you apply yourself!  go for it!', '2005-01-03 00:16:36.000000', NULL, 0),
(1087948, 130323, 23394, '<td valign="top">thanks again for a fun entry.  i should have recognized you from the title.</td>', 'thanks again for a fun entry.  i should have recognized you from the title.', '2005-01-03 00:19:21.000000', NULL, 0),
(1087949, 130807, 14012, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by cbeller:</b></div><hr/><i> finally, someone that used some creativity and put some thought into their entry. Surely a ribbon winner! Composed and executed very wel. 10 </i></td></tr></table> <br/> <br/>Looky there, I was right! :-)<br/>Excellent photo! Hopefully I can get one that great with the Tamron.<br/><br/><i>Message edited by author 2005-01-03 00:20:43.</i></td>', 'Originally posted by cbeller: finally, someone that used some creativity and put some thought into their entry. Surely a ribbon winner! Composed and executed very wel. 10   Looky there, I was right! :-)Excellent photo! Hopefully I can get one that great with the Tamron.', '2005-01-03 00:19:52.000000', '2005-01-03 00:20:43.000000', 0),
(1087962, 130571, 23394, '<td valign="top">this is one of the most underrated entries in the challenge :(<br/>great shot!  keep it up.  what''s important here is the number of comments and the score of the commenters.  you are definitely on the right track.  more than likely, it was the ''darkness'' of the image that held down your score.  better luck next time!</td>', 'this is one of the most underrated entries in the challenge :(great shot!  keep it up.  what''s important here is the number of comments and the score of the commenters.  you are definitely on the right track.  more than likely, it was the ''darkness'' of the image that held down your score.  better luck next time!', '2005-01-03 00:23:37.000000', NULL, 0),
